    aw_s->countOL = countOL;
    aw_s->countPL = countPL;
    aw_s->countQL = countQL;
    aw_s->countRL = countRL;
    aw_s->countSL = countSL;
    aw_s->countTL = countTL;
    aw_s->countUL = countUL;
    aw_s->countVL = countVL;
    aw_s->countWL = countWL;
    aw_s->countXL = countXL;
    aw_s->countYL = countYL;
    aw_s->countAR = countAR;
    aw_s->countBR = countBR;
    aw_s->countCR = countCR;
    aw_s->countDR = countDR;
    aw_s->countER = countER;
    aw_s->countFR = countFR;
    aw_s->countGR = countGR;
    aw_s->countHR = countHR;
    aw_s->countIR = countIR;
    aw_s->countJR = countJR;
