    aw_s->countZ = countZ;
    aw_s->countVLF = countVLF;
    aw_s->vibratoL = vibratoL;
    aw_s->vibratoR = vibratoR;
    aw_s->vibAL = vibAL;
    aw_s->vibAR = vibAR;
    aw_s->vibBL = vibBL;
    aw_s->vibBR = vibBR;
    aw_s->subAL = subAL;
    aw_s->subAR = subAR;
    aw_s->subBL = subBL;
    aw_s->subBR = subBR;
    aw_s->subCL = subCL;
    aw_s->subCR = subCR;
    aw_s->dBaPosL = dBaPosL;
    aw_s->dBaXL = dBaXL;
    aw_s->dBaPosR = dBaPosR;
    aw_s->dBaXR = dBaXR;
    aw_s->dBbPosL = dBbPosL;
    aw_s->dBbXL = dBbXL;
