    int countZ = aw_s->countZ;
    int countVLF = aw_s->countVLF;
    float *pearA = aw_s->pearA;
    float *pearB = aw_s->pearB;
    float *pearC = aw_s->pearC;
    float *pearD = aw_s->pearD;
