    int dBbXL = aw_s->dBbXL;
    float *dBbR = aw_s->dBbR;
    float dBbPosR = aw_s->dBbPosR;
    int dBbXR = aw_s->dBbXR;
    float *dBcL = aw_s->dBcL;
    float dBcPosL = aw_s->dBcPosL;
    int dBcXL = aw_s->dBcXL;
    float *dBcR = aw_s->dBcR;
    float dBcPosR = aw_s->dBcPosR;
    int dBcXR = aw_s->dBcXR;
    float *dBdL = aw_s->dBdL;
    float dBdPosL = aw_s->dBdPosL;
    int dBdXL = aw_s->dBdXL;
    float *dBdR = aw_s->dBdR;
    float dBdPosR = aw_s->dBdPosR;
    int dBdXR = aw_s->dBdXR;
